  const draw = () => { el.innerHTML = `<div class="klot">${blocks.map((b, k) => `<button data-k="${k}" class="kb3 ${b.big ? 'big' : ''} ${sel === k ? 'sel' : ''}" style="left:${b.c / W * 100}%;top:${b.r / H * 100}%;width:${b.w / W * 100}%;height:${b.h / H * 100}%"></button>`).join('')}<i class="kexit"></i></div><p class="muted small center">Slide the big red block out through the gap at the bottom. Select a block, then use arrows, swipe or the pad. Moves ${moves}</p>`; };
