    items.forEach(it => { g.fillStyle = it.bomb ? '#111' : it.c; g.globalAlpha = it.cut ? 0.4 : 1; g.beginPath(); g.arc(it.x, it.y, it.r, 0, 7); g.fill(); if (it.bomb) { g.fillStyle = '#ff5a3c'; g.fillRect(it.x - 2, it.y - it.r - 8, 4, 8); } g.globalAlpha = 1; });
