    if (pk.x < PR || pk.x > W - PR) { pk.vx *= -1; pk.x = Math.max(PR, Math.min(W - PR, pk.x)); } const inGoal = Math.abs(pk.x - W / 2) < GW / 2;
    if (pk.y < PR) { if (inGoal) { sc[0]++; beep(880, .2); reset(-1); } else { pk.vy *= -1; pk.y = PR; } } if (pk.y > H - PR) { if (inGoal) { sc[1]++; beep(150, .2); reset(1); } else { pk.vy *= -1; pk.y = H - PR; } }
    if (sc[0] >= 7 || sc[1] >= 7) { over = true; const won = sc[0] > sc[1]; soloEnd(o, sc[0] * 10 * o.level + (won ? 200 * o.level : 0), won); return false; } o.score(sc[0] * 10 * o.level);
    g.fillStyle = '#dff3ff'; g.fillRect(0, 0, W, H); g.strokeStyle = '#2f7cf6'; g.lineWidth = 3; g.beginPath(); g.moveTo(0, H / 2); g.lineTo(W, H / 2); g.stroke(); g.beginPath(); g.arc(W / 2, H / 2, 50, 0, 7); g.stroke(); g.fillStyle = '#123d70'; g.fillRect(W / 2 - GW / 2, 0, GW, 6); g.fillRect(W / 2 - GW / 2, H - 6, GW, 6);
