SO.twentyq = { start(el, o) { let cand = Object.keys(TQ).map(n => ({ n, w: 1 })), asked = [], q = 0, over = false, guessing = null, wrong = new Set();
  const pickQ = () => { let best = -1, bv = 1e9; TQ_ATTR.forEach((_, k) => { if (asked.includes(k)) return; const tot = sum(cand.map(c => c.w)), yes = sum(cand.filter(c => TQ[c.n][k]).map(c => c.w)); const v = Math.abs(yes - tot / 2); if (v < bv) { bv = v; best = k; } }); return best; };
  const step = () => { cand.sort((a, b) => b.w - a.w); const top = cand.filter(c => !wrong.has(c.n)); const k = pickQ(); if (q >= 20 || k < 0 || (top[0] && (top.length === 1 || top[0].w > 3 * (top[1] ? top[1].w : 0.001)) && q >= 5)) { guessing = top[0] ? top[0].n : null; } else guessing = null; return k; };
  let curQ = step(); const draw = () => { el.innerHTML = `<div class="scr"><p>Think of an animal. I'll guess it in 20 questions or fewer. Question ${q + 1}.</p>${over ? '' : guessing ? `<h3>Is it a ${esc(guessing)}?</h3><div class="row-btns"><button class="btn hot" data-a="right">Yes!</button><button class="btn" data-a="wrongg">No</button></div>` : curQ >= 0 ? `<h3>${TQ_ATTR[curQ]}</h3><div class="row-btns"><button class="btn hot" data-a="y">Yes</button><button class="btn" data-a="n">No</button><button class="btn ghost" data-a="u">Not sure</button></div>` : '<h3>You win, I give up!</h3>'}<p class="muted small">I know ${Object.keys(TQ).length} animals.</p></div>`; };
  el.addEventListener('click', e => { const b = e.target.closest('[data-a]'); if (!b || over) return; const a = b.dataset.a;
    if (a === 'right') { over = true; toast('I got it!'); soloEnd(o, 20 * o.level, false); el.querySelector('.scr').insertAdjacentHTML('beforeend', '<h3>I guessed it! Play again to try to stump me.</h3>'); return; }
    if (a === 'wrongg') { wrong.add(guessing); q++; if (!cand.some(c => !wrong.has(c.n)) || q >= 20) { over = true; soloEnd(o, 300 * o.level, true); el.querySelector('.scr').insertAdjacentHTML('beforeend', '<h3>You stumped me!</h3>'); return; } guessing = null; curQ = step(); return draw(); }
    if (a !== 'u') cand.forEach(c => { if (!!TQ[c.n][curQ] !== (a === 'y')) c.w *= 0.1; }); asked.push(curQ); q++; curQ = step(); if (curQ < 0 && !guessing) { over = true; soloEnd(o, 300 * o.level, true); } draw(); }); draw(); return () => {}; } };

// ---------- Bulls and Cows ----------
SO.bulls = { start(el, o) { const L = o.level <= 3 ? 3 : o.level <= 7 ? 4 : 5, secret = shuf('0123456789'.split('')).slice(0, L).join(''), rows = []; let over = false;
  const draw = () => { el.innerHTML = `<div class="scr"><p>Guess the ${L}-digit secret number; every digit is different. Bulls: right digit, right place. Cows: right digit, wrong place.</p><table class="lb"><tbody>${rows.map(r => `<tr><td>${r.g}</td><td class="num">${r.b} bulls</td><td class="num">${r.c} cows</td></tr>`).join('')}</tbody></table>${over ? `<h3>The number was ${secret}</h3>` : `<form class="mform"><input id="bc" maxlength="${L}" inputmode="numeric" autocomplete="off" placeholder="${L} different digits" aria-label="Your guess"><button class="btn hot">Guess</button></form>`}</div>`; const i = el.querySelector('#bc'); i && i.focus(); };
  el.addEventListener('submit', e => { e.preventDefault(); const g = el.querySelector('#bc').value.trim(); if (!new RegExp(`^\\d{${L}}$`).test(g) || new Set(g).size !== L) return toast(`Enter ${L} different digits.`); const b = [...g].filter((d, i) => secret[i] === d).length, c = [...g].filter(d => secret.includes(d)).length - b; rows.push({ g, b, c }); beep(b === L ? 880 : 500, .05);
    if (b === L || rows.length >= 12) { over = true; soloEnd(o, b === L ? (13 - rows.length) * 60 * o.level / 2 | 0 : 0, b === L); } draw(); }); draw(); return () => {}; } };

// ---------- Make 24 ----------
function solve24(ns, target = 24) { const rec = arr => { if (arr.length === 1) return Math.abs(arr[0].v - target) < 1e-6 ? arr[0].e : null; for (let i = 0; i < arr.length; i++) for (let j = 0; j < arr.length; j++) { if (i === j) continue; const a = arr[i], b = arr[j], rest = arr.filter((_, k) => k !== i && k !== j); const cands = [{ v: a.v + b.v, e: `(${a.e}+${b.e})` }, { v: a.v - b.v, e: `(${a.e}−${b.e})` }, { v: a.v * b.v, e: `(${a.e}×${b.e})` }]; if (Math.abs(b.v) > 1e-9) cands.push({ v: a.v / b.v, e: `(${a.e}÷${b.e})` }); for (const c of cands) { const r = rec(rest.concat(c)); if (r) return r; } } return null; }; return rec(ns.map(n => ({ v: n, e: String(n) }))); }
SO.game24 = { start(el, o) { let round = 0, score = 0, nums, sol, over = false, items, sel = null, op = null, left = 0, iv = null; const maxN = o.level <= 3 ? 9 : 13;
  const next = () => { if (round >= 8) { over = true; clearInterval(iv); return soloEnd(o, score, score >= 4 * 100); } round++; do { nums = [0, 0, 0, 0].map(() => 1 + R(maxN)); sol = solve24(nums); } while (!sol); items = nums.map((v, i) => ({ v, id: i })); sel = null; op = null; left = Math.max(20, 90 - o.level * 6); draw(); };
  const fmt = v => Number.isInteger(v) ? v : (Math.round(v * 100) / 100);
  const draw = () => { el.innerHTML = `<div class="scr"><p>Round ${round} of 8 · score <b>${score}</b> · <b class="t24">${left}</b>s</p><div class="tiles n24">${items.map(it => `<button data-k="${it.id}" class="${sel === it.id ? 'sel' : ''}">${fmt(it.v)}</button>`).join('')}</div><div class="row-btns">${['+', '−', '×', '÷'].map(x => `<button class="btn big ${op === x ? 'on' : ''}" data-o="${x}">${x}</button>`).join('')}</div><div class="row-btns"><button class="btn" data-a="reset">Reset</button><button class="btn ghost" data-a="skip">Show a solution</button></div><p class="muted small">Combine all four numbers with + − × ÷ to make exactly 24. Pick a number, an operation, then another number.</p></div>`; };
  el.addEventListener('click', e => { if (over) return; const k = e.target.closest('[data-k]'), x = e.target.closest('[data-o]'), a = e.target.closest('[data-a]');
    if (a) { if (a.dataset.a === 'reset') { items = nums.map((v, i) => ({ v, id: i })); sel = null; op = null; } else { toast(sol.replace(/^\((.*)\)$/, '$1') + ' = 24'); next(); return; } return draw(); }
    if (x) { if (sel !== null) op = x.dataset.o; return draw(); } if (!k) return; const id = +k.dataset.k;
    if (sel === null || op === null) { sel = id; return draw(); } if (id === sel) return; const A = items.find(i => i.id === sel), B = items.find(i => i.id === id); const v = op === '+' ? A.v + B.v : op === '−' ? A.v - B.v : op === '×' ? A.v * B.v : B.v ? A.v / B.v : NaN; if (isNaN(v)) return toast('Cannot divide by zero.');
    items = items.filter(i => i.id !== sel && i.id !== id).concat({ v, id: Math.max(...items.map(i => i.id)) + 1 }); sel = items[items.length - 1].id; op = null;
    if (items.length === 1) { if (Math.abs(v - 24) < 1e-6) { score += 100 + left * 5; o.score(score); beep(880, .1); toast('24!'); next(); return; } toast('That makes ' + fmt(v) + ', not 24.'); items = nums.map((vv, i) => ({ v: vv, id: i })); sel = null; } draw(); });
  iv = setInterval(() => { if (over) return; left--; const t = el.querySelector('.t24'); if (t) t.textContent = left; if (left <= 0) { toast('Time! ' + sol + ' = 24'); next(); } }, 1000); next(); return () => clearInterval(iv); } };

// ---------- Bingo (vs computer cards) ----------
SO.bingo = { start(el, o) { const mk = () => { const cols = [0, 1, 2, 3, 4].map(c => shuf([...Array(15)].map((_, k) => c * 15 + k + 1)).slice(0, 5)); const g = []; for (let r = 0; r < 5; r++) for (let c = 0; c < 5; c++) g.push(r === 2 && c === 2 ? 0 : cols[c][r]); return g; };
  const me = mk(), rivals = [...Array(1 + (o.level >> 2))].map(mk), balls = shuf([...Array(75)].map((_, k) => k + 1)), called = new Set([0]); const marked = new Set([12]); let over = false, iv = null; const pace = Math.max(1200, 3400 - o.level * 220);
  const lineDone = (isMarked) => { const L = []; for (let k = 0; k < 5; k++) { L.push([0, 1, 2, 3, 4].map(c => k * 5 + c), [0, 1, 2, 3, 4].map(r => r * 5 + k)); } L.push([0, 6, 12, 18, 24], [4, 8, 12, 16, 20]); return L.some(l => l.every(isMarked)); };
  const draw = () => { const last = [...called].slice(-1)[0]; el.innerHTML = `<div class="scr"><p>Last call: <b class="ball">${last ? 'BINGO'[Math.floor((last - 1) / 15)] + '-' + last : '–'}</b> · ${called.size - 1} called</p><div class="bingo">${'BINGO'.split('').map(l => `<b>${l}</b>`).join('')}${me.map((v, i) => `<button data-i="${i}" class="${marked.has(i) ? 'on' : ''}">${v || 'FREE'}</button>`).join('')}</div><button class="btn hot big" data-a="bingo">BINGO!</button><p class="muted small">Tap numbers that have been called. Claim bingo with a full row, column or diagonal before the computer's ${rivals.length > 1 ? rivals.length + ' cards' : 'card'} do.</p><p class="muted small">Called: ${[...called].filter(Boolean).slice(-15).join(', ')}</p></div>`; };
  const finish = (won, msg) => { over = true; clearInterval(iv); toast(msg); soloEnd(o, won ? Math.max(50, (75 - called.size) * 10 * o.level / 2 | 0) : 0, won); };
  el.addEventListener('click', e => { if (over) return; const b = e.target.closest('[data-i]'); if (b) { const i = +b.dataset.i; if (!called.has(me[i])) return toast('That number has not been called.'); marked.has(i) ? marked.delete(i) : marked.add(i); return draw(); } if (e.target.closest('[data-a]')) { if (lineDone(i => marked.has(i))) finish(true, 'Bingo! You win.'); else toast('No complete line yet.'); } });
  iv = setInterval(() => { if (over) return; const n = balls.pop(); if (!n) return finish(false, 'No more balls.'); called.add(n); beep(600, .05, 'sine'); draw(); if (rivals.some(rc => lineDone(i => called.has(rc[i])))) setTimeout(() => !over && finish(false, 'The computer called bingo first!'), Math.max(300, 2500 - o.level * 220)); }, pace); draw(); return () => clearInterval(iv); } };
